package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record each saved setting in the audit file, a line per setting the save sets, with the value saved, and
 *  from=<date> at its end when a from-date was given. */
public class AuditSettingChanged {
    public void audit(@Val SettingsInput input, @Val Settings settings, Audit audit) {
        String head = "SETTING_CHANGED sheet=" + settings.sheetId() + " by=" + input.user() + " key=";
        if (input.setsClerkLimit()) {
            audit.record(head + "clerk-limit value=" + SettingsResponse.text(input.clerkLimit()) + from(input, "clerk-limit"));
        }
        if (input.floor() != null) {
            audit.record(head + "floor value=" + SettingsResponse.text(input.floor()) + from(input, "floor"));
        }
        if (input.terms() != null) {
            audit.record(head + "terms value=" + input.terms() + from(input, "terms"));
        }
        input.gradeTerms().forEach((grade, days) -> audit.record(head + "terms-" + grade + " value="
                + (days != null ? days : "") + from(input, "terms-" + grade)));
        if (input.latePct() != null) {
            audit.record(head + "late-pct value=" + SettingsResponse.text(input.latePct()) + from(input, "late-pct"));
        }
        if (input.setsPolicyDate()) {
            audit.record(head + "policy-date value=" + (input.policyDate() != null ? input.policyDate() : ""));
        }
        if (input.setsPeriodNumberingFrom()) {
            audit.record(head + "period-numbering-from value="
                    + (input.periodNumberingFrom() != null ? input.periodNumberingFrom() : ""));
        }
        if (input.setsCap()) {
            audit.record(head + "cap value=" + SettingsResponse.text(input.cap()) + from(input, "cap"));
        }
        if (input.setsProofThreshold()) {
            audit.record(head + "proof-threshold value=" + SettingsResponse.text(input.proofThreshold())
                    + from(input, "proof-threshold"));
        }
        if (input.setsGraceDays()) {
            audit.record(head + "grace-days value=" + (input.graceDays() != null ? input.graceDays() : ""));
        }
        input.perms().forEach((action, roles) -> audit.record(head + "perm-" + action + " value=" + roles));
    }

    private static String from(SettingsInput input, String key) {
        var from = input.from().get(key);
        return from != null ? " from=" + from : "";
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/** A validated settings save: who is making it, and the settings it changes, in order — whether it sets the clerk
 *  limit and to what (two decimals; null: no limit), and the floor it sets (two decimals; null: left as it is) and the terms it sets (days; null: left as it is) and the late percent it sets (two decimals; null: left as it is), and whether it sets the policy date and to what (null: blank, the sheet's today), and whether it sets the period numbering from and to what (null: blank, off), and the grades whose own terms it sets
 *  (A, B, C order) and to what (days; null: none, the sheet's terms), and whether it sets the cap and to what (two
 *  decimals; null: none), and the from-dates given for the dated ones it sets, by key (one not given: from the sheet's
 *  today), and whether it sets the proof threshold and to what (two decimals; null: none), and the permission entries it sets
 *  (in action order) and to what (roles comma separated; '': the standing rule), and whether it sets the grace days and to what (days; null: off). */
public record SettingsInput(String user, boolean setsClerkLimit, BigDecimal clerkLimit, BigDecimal floor,
        Integer terms, BigDecimal latePct, boolean setsPolicyDate, LocalDate policyDate,
        boolean setsPeriodNumberingFrom, LocalDate periodNumberingFrom,
        Map<String, Integer> gradeTerms, boolean setsCap, BigDecimal cap,
        Map<String, LocalDate> from, boolean setsProofThreshold, BigDecimal proofThreshold,
        Map<String, String> perms, boolean setsGraceDays, Integer graceDays) {
}
package net.officefloor.hq.app.setting;

import java.util.Map;

/** Body of a settings save: who is making it and the settings it changes — the clerk limit (blank: no limit) and
 *  the floor and the terms (days) and the late percent and the policy date (yyyy-mm-dd; blank: the sheet's today) and the period numbering from (yyyy-mm-dd; blank: off) and grades' own terms (days by grade;
 *  blank: none, the sheet's terms) and the cap (blank: none) and the proof threshold (blank: none) and the permission matrix (roles by action, comma separated; blank: the standing rule) and the grace days (blank: off); one left out (null) is left as it is;
 *  and, by key (clerk-limit, floor, terms, terms-A/B/C, late-pct, cap, proof-threshold), the from-date (yyyy-mm-dd) a dated one it sets
 *  is recorded from (left out or blank: the sheet's today). */
public record SettingsRequest(String user, String clerkLimit, String floor, String terms, String latePct,
        String policyDate, String periodNumberingFrom, Map<String, String> gradeTerms, String cap,
        Map<String, String> from, String proofThreshold, Map<String, String> perms, String graceDays) {
}
package net.officefloor.hq.app.setting;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** The settings as the screen shows them: the clerk limit with two decimals ('' when there is none) and the floor
 *  with two decimals and the terms in days and the late percent with two decimals and the policy date (yyyy-mm-dd; '' when blank) and the period numbering from (yyyy-mm-dd; '' when off) and each grade's own
 *  terms in days ('' when it has none: it uses the sheet's terms) and the cap with two decimals ('' when there is none) and the proof threshold with two decimals ('' when there is none), all as in force on the sheet's today; and every value
 *  recorded for each dated setting, by key, oldest from-date first; and the permission matrix, by action ('' when blank); and the grace days ('' when off). */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct,
        String policyDate, String periodNumberingFrom, Map<String, String> gradeTerms, String cap,
        Map<String, List<Dated>> dated, String proofThreshold, Map<String, String> perms, String graceDays) {

    /** A dated setting's value ('' when blank) and the date (yyyy-mm-dd) it is in force from. */
    public record Dated(String from, String value) {
    }

    public static SettingsResponse from(Settings s) {
        return new SettingsResponse(SettingsResponse.text(s.clerkLimit()), SettingsResponse.text(s.floor()),
                String.valueOf(s.terms()), SettingsResponse.text(s.latePct()),
                s.policyDate() != null ? s.policyDate().toString() : "",
                s.periodNumberingFrom() != null ? s.periodNumberingFrom().toString() : "", gradeTerms(s),
                SettingsResponse.text(s.cap()), dated(s), SettingsResponse.text(s.proofThreshold()),
                s.permissions().entries(), s.graceDays() != null ? String.valueOf(s.graceDays()) : "");
    }

    private static Map<String, List<Dated>> dated(Settings s) {
        Map<String, List<Dated>> dated = new LinkedHashMap<>();
        for (String key : SettingHistory.KEYS) {
            List<Dated> values = new ArrayList<>();
            s.history().of(key).forEach((from, value) -> values.add(new Dated(from.toString(), value != null ? value : "")));
            dated.put(key, values);
        }
        return dated;
    }

    private static Map<String, String> gradeTerms(Settings s) {
        Map<String, String> terms = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer days = s.gradeTerms().get(grade);
            terms.put(grade, days != null ? String.valueOf(days) : "");
        }
        return terms;
    }

    static String text(java.math.BigDecimal limit) {
        return limit != null ? limit.toPlainString() : "";
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/** A sheet's settings in force on its today: the clerk limit (two decimals; null: no limit) the floor (two
 *  decimals) and the terms (days; a claim's due-by is its date plus them) and the late percent (two decimals) and the
 *  policy date (null: the sheet's today; a claim dated before it rounds half up, on or after it half to even) and the
 *  period numbering from (null: off; on or after it, by the sheet's today, a claim opened is numbered within its
 *  period) and the grades' own terms (days, by grade; a grade without its own uses the sheet's terms) and the cap
 *  (two decimals; null: none; a person's due-total is at most it) and the proof threshold (two decimals; null: none); and every value of the dated ones; and the permission matrix (not dated); and the grace days (null: off; not dated). */
public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms, BigDecimal latePct,
        LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, BigDecimal cap,
        BigDecimal proofThreshold, SettingHistory history, Permissions permissions, Integer graceDays) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Save the settings the input sets: each dated one recorded from its from-date (not given: the sheet's today),
 *  keeping the values already recorded (one from that same date is replaced); the policy date and the period
 *  numbering from and the grace days and the permission matrix as
 *  they are. */
public class SaveSettings {
    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input, SettingRepository repository,
            Out<Settings> settings) {
        String id = sheetId.trim();
        LocalDate today = repository.today(id);
        if (input.setsClerkLimit()) {
            repository.setDated(id, "clerk-limit", text(input.clerkLimit()), from(input, "clerk-limit", today));
        }
        if (input.floor() != null) {
            repository.setDated(id, "floor", text(input.floor()), from(input, "floor", today));
        }
        if (input.terms() != null) {
            repository.setDated(id, "terms", String.valueOf(input.terms()), from(input, "terms", today));
        }
        input.gradeTerms().forEach((grade, days) -> repository.setDated(id, "terms-" + grade,
                days != null ? String.valueOf(days) : null, from(input, "terms-" + grade, today)));
        if (input.latePct() != null) {
            repository.setDated(id, "late-pct", text(input.latePct()), from(input, "late-pct", today));
        }
        if (input.setsPolicyDate()) {
            repository.setPolicyDate(id, input.policyDate());
        }
        if (input.setsPeriodNumberingFrom()) {
            repository.setPeriodNumberingFrom(id, input.periodNumberingFrom());
        }
        if (input.setsCap()) {
            repository.setDated(id, "cap", text(input.cap()), from(input, "cap", today));
        }
        if (input.setsProofThreshold()) {
            repository.setDated(id, "proof-threshold", text(input.proofThreshold()), from(input, "proof-threshold", today));
        }
        if (input.setsGraceDays()) {
            repository.setGraceDays(id, input.graceDays());
        }
        input.perms().forEach((action, roles) -> repository.setPermission(id, action, roles));
        settings.set(repository.of(id));
    }

    private static LocalDate from(SettingsInput input, String key, LocalDate today) {
        LocalDate from = input.from().get(key);
        return from != null ? from : today != null ? today : LocalDate.of(1, 1, 1);
    }

    private static String text(BigDecimal value) {
        return value != null ? value.toPlainString() : null;
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.role.Role;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user, a clerk limit (when given)
 *  that is blank (no limit) or an amount 0.00 or more with up to two decimals, and a floor (when given) that is an
 *  amount 0.00 or more with up to two decimals, and terms (when given) that
 *  are a whole number of days, and a late percent (when given) that is a percent 0.00 or more with up to two decimals, and a policy date (when given) that is
 *  blank (the sheet's today) or a date yyyy-mm-dd, and a period numbering from (when given) that is blank (off) or a date yyyy-mm-dd, and grades' own terms (when given)
 *  only for grades A, B or C, and a cap and a proof threshold (when given) each blank (none) or an amount 0.00 or more with up to two decimals, each blank (none: the sheet's terms) or a whole number of days, and from-dates (when given) only for the dated settings, each blank (the sheet's
 *  today) or a date yyyy-mm-dd, and permission entries (when given) only for open, settle, void, reassign, close or
 *  reopen, each blank (the standing rule) or a comma separated list of clerk and steward, and grace days (when given) blank (off) or a whole number of days. */
public class ValidateSettings {
    /** The grades that may have terms of their own. */
    static final List<String> GRADES = List.of("A", "B", "C");

    private static final String PERCENT = "\\d{1,3}(\\.\\d{1,2})?";
    private static final String AMOUNT = "\\d{1,12}(\\.\\d{1,2})?";

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidSettingException("Sign in before changing settings.");
        }
        String limit = request.clerkLimit() == null ? null : request.clerkLimit().trim();
        if (limit != null && !limit.isEmpty() && !limit.matches(AMOUNT)) {
            throw new InvalidSettingException("The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank for no limit.");
        }
        String floor = request.floor() == null ? null : request.floor().trim();
        if (floor != null && !floor.matches(AMOUNT)) {
            throw new InvalidSettingException("The floor must be an amount, 0.00 or more, with up to two decimals.");
        }
        String terms = request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.matches("\\d{1,4}")) {
            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
        }
        String latePct = request.latePct() == null ? null : request.latePct().trim();
        if (latePct != null && !latePct.matches(PERCENT)) {
            throw new InvalidSettingException("The late percent must be a percent, 0.00 or more, with up to two decimals.");
        }
        String policy = request.policyDate() == null ? null : request.policyDate().trim();
        LocalDate policyDate = null;
        if (policy != null && !policy.isEmpty()) {
            try {
                policyDate = LocalDate.parse(policy);
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The policy date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
            }
        }
        String numbering = request.periodNumberingFrom() == null ? null : request.periodNumberingFrom().trim();
        LocalDate numberingFrom = null;
        if (numbering != null && !numbering.isEmpty()) {
            try {
                numberingFrom = LocalDate.parse(numbering);
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The period numbering from must be a date, yyyy-mm-dd, or blank for off.");
            }
        }
        String cap = request.cap() == null ? null : request.cap().trim();
        if (cap != null && !cap.isEmpty() && !cap.matches(AMOUNT)) {
            throw new InvalidSettingException("The cap must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
        }
        String threshold = request.proofThreshold() == null ? null : request.proofThreshold().trim();
        if (threshold != null && !threshold.isEmpty() && !threshold.matches(AMOUNT)) {
            throw new InvalidSettingException("The proof threshold must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
        }
        String grace = request.graceDays() == null ? null : request.graceDays().trim();
        if (grace != null && !grace.isEmpty() && !grace.matches("\\d{1,4}")) {
            throw new InvalidSettingException("The grace days must be a whole number of days, 0 or more, or blank for off.");
        }
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        if (request.gradeTerms() != null) {
            for (String grade : request.gradeTerms().keySet()) {
                if (!GRADES.contains(grade)) {
                    throw new InvalidSettingException("Terms may be set only for grade A, B or C.");
                }
            }
            for (String grade : GRADES) {
                if (!request.gradeTerms().containsKey(grade)) {
                    continue;
                }
                String days = request.gradeTerms().get(grade) == null ? "" : request.gradeTerms().get(grade).trim();
                if (!days.isEmpty() && !days.matches("\\d{1,4}")) {
                    throw new InvalidSettingException("The terms of grade " + grade
                            + " must be a whole number of days, 0 or more, or blank for the sheet's terms.");
                }
                gradeTerms.put(grade, days.isEmpty() ? null : Integer.valueOf(days));
            }
        }
        Map<String, String> perms = new LinkedHashMap<>();
        if (request.perms() != null) {
            for (String action : request.perms().keySet()) {
                if (!Permissions.ACTIONS.contains(action)) {
                    throw new InvalidSettingException("Permissions may be set only for open, settle, void, reassign, close or reopen.");
                }
            }
            for (String action : Permissions.ACTIONS) {
                if (!request.perms().containsKey(action)) {
                    continue;
                }
                String entry = request.perms().get(action) == null ? "" : request.perms().get(action).trim();
                List<String> roles = new ArrayList<>();
                if (!entry.isEmpty()) {
                    for (String role : entry.split(",", -1)) {
                        String r = role.trim();
                        if (!r.equals(Role.CLERK) && !r.equals(Role.STEWARD)) {
                            throw new InvalidSettingException("The roles allowed to " + action
                                    + " must be a comma separated list of clerk and steward, or blank for the standing rule.");
                        }
                        if (!roles.contains(r)) {
                            roles.add(r);
                        }
                    }
                }
                perms.put(action, String.join(",", roles));
            }
        }
        Map<String, LocalDate> from = new LinkedHashMap<>();
        if (request.from() != null) {
            for (var e : request.from().entrySet()) {
                if (!SettingHistory.KEYS.contains(e.getKey())) {
                    throw new InvalidSettingException("Only a setting that carries a figure takes a from-date.");
                }
                String date = e.getValue() == null ? "" : e.getValue().trim();
                if (date.isEmpty()) {
                    continue;
                }
                try {
                    from.put(e.getKey(), LocalDate.parse(date));
                } catch (DateTimeParseException ex) {
                    throw new InvalidSettingException("The from-date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
                }
            }
        }
        body.set(new SettingsInput(request.user().trim(), limit != null,
                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
                floor == null ? null : new BigDecimal(floor).setScale(2),
                terms == null ? null : Integer.valueOf(terms),
                latePct == null ? null : new BigDecimal(latePct).setScale(2),
                policy != null, policyDate, numbering != null, numberingFrom, gradeTerms,
                cap != null, cap == null || cap.isEmpty() ? null : new BigDecimal(cap).setScale(2), from,
                threshold != null, threshold == null || threshold.isEmpty() ? null : new BigDecimal(threshold).setScale(2),
                perms, grace != null, grace == null || grace.isEmpty() ? null : Integer.valueOf(grace)));
    }
}
    public Settings asOf(String sheetId, LocalDate end) {
        return of(sheetId, historyAsOf(sheetId, end), end);
    }

    private Settings of(String sheetId, SettingHistory history, LocalDate today) {
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer days = history.gradeTermsOn(grade, today);
            if (days != null) {
                gradeTerms.put(grade, days);
            }
        }
        return new Settings(sheetId, history.clerkLimitOn(today), history.floorOn(today), history.termsOn(today),
                history.latePctOn(today), policyDate(sheetId), periodNumberingFrom(sheetId), gradeTerms,
                history.capOn(today), history.proofThresholdOn(today), history, permissions(sheetId), graceDays(sheetId));
    }

    /** Every value of the sheet's dated settings, by key and from-date. */
    public SettingHistory history(String sheetId) {
        Map<String, NavigableMap<LocalDate, String>> values = new HashMap<>();
